WITH enriched AS (SELECT id, store_id, product_id, sale_date, LAG(units) OVER (PARTITION BY store_id ORDER BY revenue, id) AS prev_units, LAG(revenue) OVER (PARTITION BY store_id ORDER BY revenue, id) AS prev_revenue, LEAD(revenue) OVER (PARTITION BY store_id ORDER BY revenue, id) AS next_revenue, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY revenue, id) AS event_seq, AVG(revenue) OVER (PARTITION BY store_id) AS store_id_avg_revenue FROM store_sales) SELECT CASE WHEN prev_revenue >= 4000 THEN 'HIGH' ELSE 'LOW' END AS prev_revenue_tier, PERCENTILE_APPROX(event_seq, 0.5) AS event_seq_p50, ROUND(AVG(event_seq), 2) AS avg_event_seq, MIN(prev_revenue) AS min_prev_revenue FROM enriched GROUP BY CASE WHEN prev_revenue >= 4000 THEN 'HIGH' ELSE 'LOW' END HAVING PERCENTILE_APPROX(event_seq, 0.5) < 1000000 ORDER BY event_seq_p50
